#' Derive scenario from data
#'
#' Estimates a library scenario from the open dataset: the marginal 
#' distribution of each variable, their latent correlations and the 
#' conditional effects on the outcome. Simulated studies from it resemble the 
#' data. The data cannot tell causes from correlates: the scenario has 
#' undirected correlations, to be turned into a causal structure before 
#' teaching (by you, or an AI with the exported file).
#' 
#'
#' @examples
#' \donttest{
#' # studysim:::derive_scenario(df, "outcome", covs = c("x1", "x2"))
#'}
#' @param data .
#' @param outcome .
#' @param time .
#' @param covs .
#' @param outcomeType .
#' @param logOutcome .
#' @param missingMethod how the outcome model handles missing covariates;
#'   multiple imputation is the most accurate and the slowest
#' @param imputations .
#' @param scenarioId .
#' @param scenarioLabel .
#' @param sourceName .
#' @param validate .
#' @param exportFormat .
#' @param exportScenario .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$notice} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$variables} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$effects} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$correlations} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$yaml} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$exportState} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$variables$asDF}
#'
#' \code{as.data.frame(results$variables)}
#'
#' @export
simDerive <- function(
    data,
    outcome,
    time = NULL,
    covs,
    outcomeType = "auto",
    logOutcome = FALSE,
    missingMethod = "complete",
    imputations = 20,
    scenarioId = "derived_scenario",
    scenarioLabel = "",
    sourceName = "",
    validate = TRUE,
    exportFormat = "yaml",
    exportScenario = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("simDerive requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(time)) time <- jmvcore::resolveQuo(jmvcore::enquo(time))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(time), time, NULL),
            `if`( ! missing(covs), covs, NULL))


    options <- simDeriveOptions$new(
        outcome = outcome,
        time = time,
        covs = covs,
        outcomeType = outcomeType,
        logOutcome = logOutcome,
        missingMethod = missingMethod,
        imputations = imputations,
        scenarioId = scenarioId,
        scenarioLabel = scenarioLabel,
        sourceName = sourceName,
        validate = validate,
        exportFormat = exportFormat,
        exportScenario = exportScenario)

    analysis <- simDeriveClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

